drop table if exists system_administrative_division;
create table system_administrative_division
(
    id          char(20)              not null comment '主键' primary key,
    deleted     boolean default false not null comment '逻辑删除',
    create_time datetime              not null comment '创建时间',
    update_time datetime              not null comment '修改时间',
    code        varchar(16)           not null comment '区划代码',
    name        varchar(16)           not null comment '名称',
    level       smallint              not null comment '区划级别',
    parent_code char(16)              not null comment '上级区划'
) comment '行政区划';

